class Req : IAuthorizationRequirement;

class ByRole(string role) : AuthorizationHandler<Req> {
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext c, Req r) {
        if (c.User.IsInRole(role)) c.Succeed(r);
        return Task.CompletedTask;
    }
}

