class OwnerHandler : AuthorizationHandler<
    OperationAuthorizationRequirement, Doc>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext c,
        OperationAuthorizationRequirement r, Doc d)
    {
        if (c.User.FindFirstValue(
                ClaimTypes.NameIdentifier) == d.OwnerId)
            c.Succeed(r);
        return Task.CompletedTask;
    }
}
